<script setup lang="ts">
import {ref,nextTick,onMounted,onBeforeUnmount} from 'vue';
import {request} from './service';
const data=ref<any>({templates:{},flows:[],runs:[],paused:false}),form=ref<any>(null),selected=ref<any>(null),busy=ref(''),notice=ref('');let timer:any;
const quarters=(()=>{const now=new Date(),end=now.getFullYear()*100+Math.floor(now.getMonth()/3)*3+1,result:string[]=[];for(let year=2024;year<=now.getFullYear();year++)for(const month of [1,4,7,10]){const value=year*100+month;if(value>=202407&&value<=end)result.push(String(value));}return result.reverse();})();
const states={queued:'等待运行',running:'正在采集',waiting_approval:'等待你确认',waiting_executor:'等待本地资料',succeeded:'完成',failed:'来源失败',canceled:'已取消',sending:'正在投递',email_pending:'准备投递',delivery_failed:'邮件失败',delivery_unknown:'邮件结果未知'};
async function selectRun(run){try{selected.value=await request('/api/private/automation/runs/'+run.id);}catch(e){notice.value=e.message;}}
async function load(){data.value=await request('/api/private/automation?compact=true');if(selected.value){const row=data.value.runs.find(r=>r.id===selected.value.id);if(row&&(row.updated!==selected.value.updated||row.state!==selected.value.state))await selectRun(row);}}
function create(template='seasonal-anime'){form.value={name:data.value.templates[template].name,template,enabled:false,config:{schedule:'manual',sendTime:'09:00',timezone:'Asia/Shanghai',weekday:0,quarter:'auto',limit:0,saveDocument:true,saveLibrary:template==='seasonal-anime',email:false}};}
async function edit(flow){form.value={...flow,config:{...flow.config}};await nextTick();document.querySelector('.auto-form')?.scrollIntoView({behavior:'smooth',block:'start'});}
async function action(key,fn){busy.value=key;notice.value='';try{await fn();await load();}catch(e){notice.value=e.message;}finally{busy.value='';}}
async function save(){await action('save',async()=>{const f=form.value;await request('/api/private/automation/flows'+(f.id?'/'+f.id:''),f.id?'PUT':'POST',f);form.value=null;notice.value='任务设置已保存，修改只影响之后的运行。';});}
async function run(flow){await action(flow.id,async()=>{const r=await request(`/api/private/automation/flows/${flow.id}/run`,'POST',{key:crypto.randomUUID()});selected.value=r;notice.value='任务已排队，结果会保留并等待你的确认。';});}
async function remove(flow){if(!confirm(`删除任务“${flow.name}”？已有运行记录会保留。`))return;await action('delete',async()=>{await request(`/api/private/automation/flows/${flow.id}`,'DELETE',{version:flow.version});if(form.value?.id===flow.id)form.value=null;notice.value='任务已删除，运行记录已保留。';});}
async function approve(run){await action('approve',async()=>{selected.value=await request(`/api/private/automation/runs/${run.id}/approve`,'POST',{});});}
async function cancel(run){await action('cancel',()=>request(`/api/private/automation/runs/${run.id}/cancel`,'POST',{}));}
async function pause(){await action('pause',()=>request('/api/private/automation/pause','PUT',{paused:!data.value.paused}));}
async function retryMail(run){await action('retry',()=>request(`/api/private/automation/runs/${run.id}/retry-email`,'POST',{}));}
onMounted(async()=>{try{await load();timer=setInterval(()=>{if(!document.hidden&&!busy.value)load().catch(()=>{});},5000);}catch(e){notice.value=e.message;}});onBeforeUnmount(()=>clearInterval(timer));
</script>
<template>
<section class="automation-page"><header class="automation-heading"><div><span class="space-eyebrow">AUTOMATION / YOUR SMALL HELPERS</span><h1>让琐事自己走一段。</h1><p>云端处理轻量采集与保存，本地 AI 处理浏览器、摘要与复杂资料。结果默认等待你确认。</p></div><el-button :type="data.paused?'success':'warning'" plain :loading="busy==='pause'" @click="pause">{{data.paused?'恢复自动化':'暂停全部自动化'}}</el-button></header>
<p v-if="notice" role="status" class="auto-notice">{{notice}}</p>
<div class="template-cards"><button v-for="(item,key) in data.templates" :key="key" @click="create(String(key))"><small>{{item.execution==='local'?'LOCAL → CLOUD':'CLOUD / LIGHTWEIGHT'}}</small><h2>{{item.name}}</h2><p>{{item.steps.join(' → ')}}</p><strong>＋ 配置任务</strong></button></div>
<section v-if="form" class="auto-form"><header><h2>{{form.id?'编辑任务':'新建任务'}}</h2><el-button @click="form=null">关闭</el-button></header><form @submit.prevent="save"><label>任务名称<el-input v-model="form.name" maxlength="100" required/></label><label v-if="form.template!=='local-digest'">触发计划<el-select v-model="form.config.schedule"><el-option label="仅手动运行" value="manual"/><el-option label="每天" value="daily"/><el-option label="每周" value="weekly"/><el-option label="季度首日" value="quarterly"/></el-select></label><template v-if="form.config.schedule!=='manual'"><label>时间（HH:mm）<el-input v-model="form.config.sendTime" placeholder="09:00"/></label><label>时区<el-input v-model="form.config.timezone"/></label><label v-if="form.config.schedule==='weekly'">星期<el-select v-model="form.config.weekday"><el-option v-for="(d,i) in ['一','二','三','四','五','六','日']" :key="i" :label="'星期'+d" :value="i"/></el-select></label><label><el-switch v-model="form.enabled"/>启用自动触发</label></template><template v-if="form.template==='seasonal-anime'"><label>季度<el-select v-model="form.config.quarter" filterable><el-option label="当前季度（自动）" value="auto"/><el-option v-for="quarter in quarters" :key="quarter" :label="quarter.slice(0,4)+' 年 '+quarter.slice(4)+' 月'" :value="quarter"/></el-select></label><label>最多读取条数（0 为全部，最多 200 条）<el-input-number v-model="form.config.limit" :min="0" :max="200"/></label></template><fieldset><legend>确认后的输出</legend><el-checkbox v-model="form.config.saveDocument">保存私有文档</el-checkbox><el-checkbox v-if="form.template==='seasonal-anime'" v-model="form.config.saveLibrary">加入番剧收藏（去重）</el-checkbox><el-checkbox v-model="form.config.email">发送到已配置的站主邮箱</el-checkbox></fieldset><el-button type="primary" native-type="submit" :loading="busy==='save'">保存任务</el-button></form></section>
<section class="flow-list"><h2>我的任务</h2><el-empty v-if="!data.flows.length" description="从上面的模板配置第一条任务" :image-size="60"/><article v-for="flow in data.flows" :key="flow.id"><div><h3>{{flow.name}}</h3><p>{{data.templates[flow.template]?.name}} · {{flow.enabled?'自动计划已启用':'自动计划已关闭'}} · v{{flow.version}}</p><small v-if="flow.template==='local-digest'">Flow ID：<code>{{flow.id}}</code></small></div><el-button @click="edit(flow)">编辑</el-button><el-button type="danger" plain :loading="busy==='delete'" @click="remove(flow)">删除</el-button><el-button v-if="flow.template!=='local-digest'" type="primary" :loading="busy===flow.id" :disabled="data.paused" @click="run(flow)">运行并预览</el-button><RouterLink v-else to="/access-tokens">配置本地接入 ↗</RouterLink></article></section>
<div class="auto-result-grid"><section class="run-list"><header><h2>运行记录</h2><el-button size="small" @click="load">刷新</el-button></header><p v-if="!data.runs.length">还没有运行记录。</p><button v-for="run in data.runs" :key="run.id" :class="{selected:selected?.id===run.id}" @click="selectRun(run)"><strong>{{run.name}}</strong><span>{{states[run.state]||run.state}}</span><small>{{new Date(run.created).toLocaleString()}}</small></button></section><section v-if="selected" class="run-detail"><header><div><h2>{{selected.result.title||selected.snapshot.name}}</h2><el-tag>{{states[selected.state]||selected.state}}</el-tag></div><el-button v-if="['queued','running','waiting_approval','waiting_executor','failed'].includes(selected.state)" @click="cancel(selected)">取消运行</el-button></header><p v-if="selected.error" role="alert">{{selected.error}}</p><p v-if="selected.state==='running'">正在读取受限来源并处理封面，请稍候…</p><p v-if="selected.state==='waiting_executor'">本地 AI 可使用 <code>POST /api/v1/automation/results</code> 主动提交；Flow ID 见任务列表。</p><ul v-if="selected.result.warnings?.length"><li v-for="message in selected.result.warnings" :key="message">{{message}}</li></ul><div v-if="selected.result.items?.length" class="season-items"><article v-for="item in selected.result.items" :key="item.sourceKey"><img v-if="item.cover" :src="item.cover" :alt="item.title" loading="lazy"/><div v-else class="cover-placeholder">暂无封面</div><h3>{{item.title}}</h3><p>{{item.broadcast}}</p><small>{{item.tags}}</small><a :href="item.url" target="_blank" rel="noopener noreferrer">Yuciwiki 来源 ↗</a></article></div><pre v-if="selected.result.text">{{selected.result.text}}</pre><footer><el-button v-if="selected.state==='waiting_approval'" type="primary" :loading="busy==='approve'" @click="approve(selected)">确认保存{{selected.snapshot.config.email?'并发送邮件':''}}</el-button><el-button v-if="selected.state==='delivery_failed'" :loading="busy==='retry'" @click="retryMail(selected)">重试邮件</el-button><RouterLink v-if="selected.result.documentId" to="/documents">查看已保存文档 ↗</RouterLink><small v-if="selected.result.added!==undefined">新增收藏 {{selected.result.added}} 项</small></footer></section><section v-else class="run-detail auto-empty"><h2>每一步，都留有记录。</h2><p>选择运行记录查看结果；失败不会生成一份看起来成功的报告。</p></section></div>
</section></template>
<style scoped>
.automation-page{max-width:1320px;margin:auto}.automation-heading,.auto-form header,.flow-list article,.run-list header,.run-detail header{display:flex;justify-content:space-between;align-items:center;gap:16px}.automation-heading h1{font-size:29px;margin:12px 0}.automation-heading p,.template-cards p,.flow-list p,.run-list p,.auto-empty p{font-size:13px;color:var(--studio-muted);line-height:1.8}.template-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:28px 0}.template-cards>button{background:var(--studio-panel);border:1px solid var(--studio-line);border-radius:10px;padding:20px;text-align:left;cursor:pointer;color:inherit;transition:transform .2s,border-color .2s}.template-cards>button:hover{transform:translateY(-4px);border-color:#8d79a2}.template-cards h2{font-size:19px;margin:12px 0}.template-cards small{font-size:9px;letter-spacing:1.6px;color:var(--studio-muted)}.template-cards strong{font-size:12px}.auto-form,.flow-list,.auto-result-grid{margin-top:26px;border-top:1px solid var(--studio-line);padding-top:20px}.auto-form h2,.flow-list h2,.run-list h2,.run-detail h2{font-size:20px}.auto-form form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:18px}.auto-form label{display:grid;gap:8px;font-size:12px}.auto-form fieldset{grid-column:1/-1;border:0;padding:0}.auto-form legend{font-size:12px;margin-bottom:8px}.auto-form form>button{justify-self:start}.flow-list article{padding:18px 0;border-bottom:1px solid var(--studio-line);flex-wrap:wrap}.flow-list article>div{flex:1;min-width:200px}.flow-list h3{font-size:16px;margin:0}.flow-list small{font-size:11px;color:var(--studio-muted);overflow-wrap:anywhere}.flow-list a{font-size:12px}.auto-result-grid{display:grid;grid-template-columns:290px minmax(0,1fr);gap:22px}.run-list>button{display:grid;width:100%;gap:7px;text-align:left;border:1px solid var(--studio-line);border-radius:6px;background:var(--studio-panel);padding:13px;margin-top:10px;color:inherit;cursor:pointer}.run-list>button.selected{border-color:#8d79a2}.run-list strong{font-size:13px}.run-list span,.run-list small{font-size:11px;color:var(--studio-muted)}.run-detail{min-width:0;padding:22px;background:var(--studio-panel);border:1px solid var(--studio-line);border-radius:10px}.run-detail pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.8 ui-monospace,Consolas,monospace;max-height:470px;overflow:auto;margin:20px 0}.run-detail>p,.run-detail li{font-size:12px;line-height:1.8}.run-detail footer{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.run-detail footer a,.run-detail footer small{font-size:12px}.season-items{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:22px 0}.season-items img,.cover-placeholder{width:100%;height:180px;object-fit:cover;background:var(--studio-bg);border-radius:5px}.cover-placeholder{display:grid;place-items:center;color:var(--studio-muted);font-size:11px}.season-items h3{font-size:13px;margin:10px 0 5px}.season-items p,.season-items small,.season-items a{display:block;font-size:11px;line-height:1.7;color:var(--studio-muted)}.auto-notice{font-size:12px;margin-top:14px}@media(max-width:950px){.auto-result-grid{grid-template-columns:1fr}.run-list{max-height:310px;overflow:auto}}@media(max-width:650px){.template-cards{grid-template-columns:1fr}.automation-heading{align-items:flex-start;flex-direction:column}.automation-heading h1{font-size:25px}.auto-form form{grid-template-columns:1fr}.auto-form fieldset{grid-column:auto}.run-detail{padding:15px}.season-items{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
